#include "bank.h"

#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

static int send_all(int fd, const void *buf, size_t n) { const char *p=buf;ssize_t w;while(n){w=send(fd,p,n,0);if(w<=0)return -1;p+=w;n-=(size_t)w;}return 0; }
static int recv_all(int fd, void *buf, size_t n) { char *p=buf;ssize_t x;while(n){x=recv(fd,p,n,0);if(x<=0)return -1;p+=x;n-=(size_t)x;}return 0; }
static void ask(const char *label,char *out,size_t size) { printf("%s",label);fflush(stdout);if(!fgets(out,(int)size,stdin)){out[0]=0;return;}out[strcspn(out,"\r\n")]=0; }
static int ask_int(const char *label) { char b[64];ask(label,b,sizeof b);return atoi(b); }
static double ask_money(const char *label) { char b[64];ask(label,b,sizeof b);return strtod(b,NULL); }
static void send_request(int fd,Request *q,Response *r) { if(send_all(fd,q,sizeof *q)||recv_all(fd,r,sizeof *r)){fprintf(stderr,"Server connection closed.\n");exit(EXIT_FAILURE);}printf("\n%s\n",r->message);if(r->data[0])printf("%s",r->data);if(r->balance!=0||q->operation==OP_BALANCE)printf("Balance: %.2f\n",r->balance); }
static void clean(Request *q,int op) { memset(q,0,sizeof *q);q->operation=op;q->amount=-1; }
static void customer_menu(int fd) { Request q;Response r;for(;;){int n;printf("\nCustomer\n1 Balance  2 Deposit  3 Withdraw  4 Transfer\n5 Apply loan  6 Change password  7 Feedback  8 History\n9 My loan status  10 Logout  0 Exit\n");n=ask_int("Choice: ");if(n==0||n==10){clean(&q,n==0?OP_EXIT:OP_LOGOUT);send_request(fd,&q,&r);return;}if(n==1)clean(&q,OP_BALANCE);else if(n==2){clean(&q,OP_DEPOSIT);q.amount=ask_money("Deposit amount: ");}else if(n==3){clean(&q,OP_WITHDRAW);q.amount=ask_money("Withdrawal amount: ");}else if(n==4){clean(&q,OP_TRANSFER);ask("Recipient username: ",q.target,sizeof q.target);q.amount=ask_money("Amount: ");}else if(n==5){clean(&q,OP_APPLY_LOAN);q.amount=ask_money("Requested amount: ");ask("Loan note/purpose: ",q.text,sizeof q.text);}else if(n==6){clean(&q,OP_CHANGE_PASSWORD);ask("New password: ",q.password,sizeof q.password);}else if(n==7){clean(&q,OP_FEEDBACK);ask("Feedback: ",q.text,sizeof q.text);}else if(n==8)clean(&q,OP_HISTORY);else if(n==9)clean(&q,OP_LIST_MY_LOANS);else {puts("Invalid choice.");continue;}send_request(fd,&q,&r);if(!r.ok&&strstr(r.message,"session has ended")){puts("You have been logged out.");return;}} }
static void employee_menu(int fd) { Request q;Response r;for(;;){int n;printf("\nEmployee\n1 Add customer  2 Modify customer  3 Close customer account\n4 Assigned loans  5 Approve/reject assigned loan  6 Customer passbook\n7 Change password  8 Logout  0 Exit\n");n=ask_int("Choice: ");if(n==0||n==8){clean(&q,n==0?OP_EXIT:OP_LOGOUT);send_request(fd,&q,&r);return;}if(n==1){clean(&q,OP_ADD_CUSTOMER);ask("Customer username: ",q.username,sizeof q.username);ask("Initial password: ",q.password,sizeof q.password);ask("Full name: ",q.text,sizeof q.text);q.amount=ask_money("Opening balance: ");}else if(n==2){clean(&q,OP_MODIFY_USER);ask("Customer username: ",q.target,sizeof q.target);ask("New full name (blank keeps existing): ",q.text,sizeof q.text);q.amount=ask_money("New balance (-1 keeps existing): ");}else if(n==3){clean(&q,OP_CLOSE_ACCOUNT);ask("Customer username: ",q.target,sizeof q.target);}else if(n==4)clean(&q,OP_LIST_ASSIGNED_LOANS);else if(n==5){clean(&q,OP_LOAN_DECISION);q.id=ask_int("Loan ID: ");q.amount=ask_int("Decision: 1 approve, 2 reject: ");ask("Decision note: ",q.text,sizeof q.text);}else if(n==6){clean(&q,OP_CUSTOMER_HISTORY);ask("Customer username: ",q.target,sizeof q.target);}else if(n==7){clean(&q,OP_CHANGE_PASSWORD);ask("New password: ",q.password,sizeof q.password);}else {puts("Invalid choice.");continue;}send_request(fd,&q,&r);} }
static void manager_menu(int fd) { Request q;Response r;for(;;){int n;printf("\nManager\n1 Activate/deactivate customer  2 View pending loan applications\n3 Assign loan to employee  4 Review feedback  5 List employees\n6 Change password  7 Logout  0 Exit\n");n=ask_int("Choice: ");if(n==0||n==7){clean(&q,n==0?OP_EXIT:OP_LOGOUT);send_request(fd,&q,&r);return;}if(n==1){clean(&q,OP_ACCOUNT_STATE);ask("Customer username: ",q.target,sizeof q.target);q.id=ask_int("State: 1 activate, 0 deactivate: ");}else if(n==2)clean(&q,OP_LIST_PENDING_LOANS);else if(n==3){clean(&q,OP_ASSIGN_LOAN);q.id=ask_int("Loan ID: ");ask("Employee username: ",q.target,sizeof q.target);}else if(n==4)clean(&q,OP_LIST_FEEDBACK);else if(n==5)clean(&q,OP_LIST_EMPLOYEES);else if(n==6){clean(&q,OP_CHANGE_PASSWORD);ask("New password: ",q.password,sizeof q.password);}else{puts("Invalid choice.");continue;}send_request(fd,&q,&r);} }
static void admin_menu(int fd) { Request q;Response r;for(;;){int n;printf("\nAdministrator\n1 Add customer  2 Add employee  3 Add manager\n4 Modify user  5 Manage user role  6 Activate/deactivate customer, employee, or manager\n7 Change password  8 Logout  0 Exit\n");n=ask_int("Choice: ");if(n==0||n==8){clean(&q,n==0?OP_EXIT:OP_LOGOUT);send_request(fd,&q,&r);return;}if(n>=1&&n<=3){clean(&q,n==1?OP_ADD_CUSTOMER:n==2?OP_ADD_EMPLOYEE:OP_ADD_MANAGER);ask("Username: ",q.username,sizeof q.username);ask("Initial password: ",q.password,sizeof q.password);ask("Full name: ",q.text,sizeof q.text);if(n==1)q.amount=ask_money("Opening balance: ");}else if(n==4){clean(&q,OP_MODIFY_USER);ask("User username: ",q.target,sizeof q.target);ask("New full name (blank keeps existing): ",q.text,sizeof q.text);}else if(n==5){clean(&q,OP_SET_ROLE);ask("User username: ",q.target,sizeof q.target);q.role=ask_int("Role: 1 customer, 2 employee, 3 manager, 4 admin: ");}else if(n==6){clean(&q,OP_ACCOUNT_STATE);ask("Customer, employee, or manager username: ",q.target,sizeof q.target);q.id=ask_int("State: 1 activate, 0 deactivate: ");}else if(n==7){clean(&q,OP_CHANGE_PASSWORD);ask("New password: ",q.password,sizeof q.password);}else{puts("Invalid choice.");continue;}send_request(fd,&q,&r);} }
int main(int argc,char **argv) { const char *host=argc>1?argv[1]:"127.0.0.1";int fd,role,port=argc>2?atoi(argv[2]):BANK_PORT;struct sockaddr_in addr;Request q;Response r;if(port<1024||port>65535){fprintf(stderr,"Port must be between 1024 and 65535.\n");return 1;}fd=socket(AF_INET,SOCK_STREAM,0);if(fd<0){perror("socket");return 1;}memset(&addr,0,sizeof addr);addr.sin_family=AF_INET;addr.sin_port=htons((uint16_t)port);if(inet_pton(AF_INET,host,&addr.sin_addr)!=1){fprintf(stderr,"Use an IPv4 address.\n");return 1;}if(connect(fd,(struct sockaddr*)&addr,sizeof addr)<0){perror("connect");return 1;}puts("Banking Management System");for(;;){role=ask_int("Role: 1 customer, 2 employee, 3 manager, 4 administrator, 0 exit: ");if(role==0){close(fd);return 0;}if(role<1||role>4){puts("Invalid role.");continue;}clean(&q,OP_LOGIN);q.role=role;ask("Username: ",q.username,sizeof q.username);ask("Password: ",q.password,sizeof q.password);send_request(fd,&q,&r);if(!r.ok)continue;if(role==ROLE_CUSTOMER)customer_menu(fd);else if(role==ROLE_EMPLOYEE)employee_menu(fd);else if(role==ROLE_MANAGER)manager_menu(fd);else admin_menu(fd);break;}close(fd);return 0; }
